    return None

def agent_action(sandbox, agent_body, step_count):
    pos = sandbox.get_sled_position()
    if pos is None:
        return
    x, y = pos
    vel = sandbox.get_sled_velocity() or (0.0, 0.0)
    vx, vy = vel[0], vel[1]
    speed = math.sqrt(vx * vx + vy * vy)

    past_a = sandbox.get_checkpoint_a_reached()
    past_b = sandbox.get_checkpoint_b_reached()

    # Determine target based on progress
    if not past_a:
        target_x, target_y = 18.0, 4.2  # Alpha center
    elif not past_b:
        target_x, target_y = 23.75, 2.85  # Beta center
    else:
        target_x, target_y = 30.0, 2.5  # Final target

    dx = target_x - x
    dy = target_y - y

    # Desired speed
    desired_speed = 4.5

    # Desired velocity vector
    distance = math.sqrt(dx**2 + dy**2)
    if distance < 0.1:
        fx, fy = 0.0, 0.0
    else:
        desired_vx = (dx / distance) * desired_speed
        desired_vy = (dy / distance) * desired_speed

        # Proportional control for position error
        K_X = 100.0  # Horizontal thrust gain
        K_Y = 800.0  # Vertical thrust gain
        fx = K_X * dx
        fy = K_Y * dy

        # Adjust for vertical position if near checkpoint
        if not past_a and (17.5 <= x <= 19.0):
            if y < target_y - 0.2:
                fy += 300.0  # Lift up
            elif y > target_y + 0.2:
                fy -= 300.0  # Descend
        elif not past_b and (23.0 <= x <= 24.5):
            if y < target_y - 0.2:
                fy += 300.0
            elif y > target_y + 0.2:
                fy -= 300.0

        # Adjust for velocity
        if speed < 2.0:
            fx *= 1.5
            fy *= 1.5
        elif speed > 6.0:
            fx *= 0.7
            fy *= 0.7

        # Wind zone adjustment (x = 14–28)
        if 14.0 <= x <= 28.0:
            # Apply horizontal thrust based on current velocity to counteract wind
            if vx > 0:
                fx += 100.0  # Counteract wind pushing backward
            elif vx < 0:
                fx += 400.0  # Stronger correction if moving backward

        # After passing Beta, ensure forward motion
        if past_b:
            if vx < 0:
                fx += 400.0  # Prevent backward drift
            elif vx > 0:
                fx += 300.0  # Maintain forward momentum

        # Scale to MAX_THRUST
        MAX_THRUST = 600.0
        f = math.sqrt(fx**2 + fy**2)
        if f > MAX_THRUST:
            scale = MAX_THRUST / f
            fx *= scale
            fy *= scale

    sandbox.apply_thrust(fx, fy)

